      "type": "string",
      "minLength": 1
    },
    "ts": {
      "type": "string",
      "format": "date-time"
    },
    "tool": {
      "type": "string",
      "minLength": 1
    },
    "operation": {
      "enum": [
        "read",
        "write",
        "unknown"
      ]
    },
    "mode": {
      "enum": [
        "observe",
        "repair",
        "strict"
      ]
    },
    "drift": {
      "anyOf": [
        {
